node - <<'NODE'
const fs = require('fs');
const crypto = require('crypto');
const manifestBytes = fs.readFileSync('run-manifest.json');
const manifest = JSON.parse(manifestBytes);
const receipt = JSON.parse(fs.readFileSync('out/receipt.json', 'utf8'));
const sha = data => crypto.createHash('sha256').update(data).digest('hex');
if (sha(manifestBytes) !== receipt.full_manifest_digest.digest) throw Error('full digest mismatch');
const expected = manifest.evidence.map(e => sha(JSON.stringify(e)));
const actual = receipt.evidence_digests.map(e => e.digest);
if (JSON.stringify(expected) !== JSON.stringify(actual)) throw Error('evidence digest mismatch');
for (const file of ['out/receipt.json', 'out/receipt.svg']) {
